Method.Source:
/// <summary>
/// PaffH 07.06.21
/// </summary>
/// <param name = "_userId">UserId</param>
/// <returns>UserId</returns>
[DataMember,
    SysOperationLabel('@NDX:NDXForUser'),
    SysOperationDisplayOrder('1')]
public UserId parmUserId(UserId _userId = UserId)
{
    userId = _userId;
    return UserId;
}

/// <summary>
/// PaffH 07.06.21
/// </summary>
/// <param name = "_dateFrom">TransDate</param>
/// <returns>TransDate</returns>
[DataMember,
    SysOperationLabel('@NDX:NDXFrom'),
    SysOperationDisplayOrder('2')]
public TransDate parmDateFrom(TransDate _dateFrom = dateFrom)
{
    dateFrom = _dateFrom;
    return dateFrom;
}

/// <summary>
/// PaffH 07.06.21
/// </summary>
/// <param name = "_dateTo">TransDate</param>
/// <returns>TransDate</returns>
[DataMember,
    SysOperationLabel('@NDX:NDXTo'),
    SysOperationDisplayOrder('3')]
public TransDate parmDateTo(TransDate _dateTo = dateTo)
{
    dateTo = _dateTo;
    return dateTo;
}

/// <summary>
/// PaffH 07.06.21
/// </summary>
/// <param name = "_dateFrom">TransDate</param>
/// <returns>utcdatetime</returns>
public utcdatetime parmUtcDateTimeFrom(TransDate _dateFrom = dateFrom)
{
    return DateTimeUtil::parse(NDXHelperCommon::DateTimeStringForParser(_dateFrom));
}

/// <summary>
/// PaffH 07.06.21
/// </summary>
/// <param name = "_dateTo">TransDate</param>
/// <returns>utcdatetime</returns>
public utcdatetime parmUtcDateTimeTo(TransDate _dateTo = dateTo)
{
    return DateTimeUtil::parse(NDXHelperCommon::DateTimeStringForParser(_dateTo, true));
}

/// <summary>
/// PaffH 07.06.21
/// </summary>
protected void new()
{
    dateTo = NDXHelperCommon::SystemDateGet();
    dateFrom = dateTo - 1;
    userId = curUserId();
}
